+// Introsort (QuickSort + Insertion Sort + Heapsort fallback) for small partitions
+static void insertion_sort(uint32_t* a, size_t n) {
+    for (size_t i = 1; i < n; ++i) {
+        uint32_t key = a[i];
+        size_t j = i;
+        while (j > 0 && a[j - 1] > key) {
+            a[j] = a[j - 1];
+            --j;
+        }
+        a[j] = key;
+    }
 }

+static void heapify(uint32_t* a, size_t n, size_t i) {
+    size_t largest = i;
+    size_t l = 2 * i + 1;
+    size_t r = 2 * i + 2;
+    if (l < n && a[l] > a[largest]) largest = l;
+    if (r < n && a[r] > a[largest]) largest = r;
+    if (largest != i) {
+        std::swap(a[i], a[largest]);
+        heapify(a, n, largest);
+    }
+}
+
+static void heap_sort(uint32_t* a, size_t n) {
+    for (size_t i = n / 2; i-- > 0;) heapify(a, n, i);
+    for (size_t i = n; i-- > 1;) {
+        std::swap(a[0], a[i]);
+        heapify(a, i, 0);
+    }
+}
+
+static int partition(uint32_t* a, size_t lo, size_t hi) {
+    size_t mid = lo + (hi - lo) / 2;
+    if (a[lo] > a[mid]) std::swap(a[lo], a[mid]);
+    if (a[lo] > a[hi - 1]) std::swap(a[lo], a[hi - 1]);
+    if (a[mid] > a[hi - 1]) std::swap(a[mid], a[hi - 1]);
+    std::swap(a[mid], a[lo + 1]);
+    uint32_t pivot = a[lo + 1];
+    size_t i = lo, j = hi - 1;
+    while (true) {
+        while (a[++i] < pivot);
+        while (a[--j] > pivot);
+        if (i < j) std::swap(a[i], a[j]);
+        else return i;
+    }
+}
+
+static void introsort_impl(uint32_t* a, size_t lo, size_t hi, int max_depth) {
+    while (hi - lo > 32) {
+        if (max_depth == 0) {
+            std::swap(a[lo], a[hi - 1]);
+            heap_sort(a + lo, hi - lo);
+            return;
+        }
+        --max_depth;
+        size_t p = partition(a, lo, hi);
+        if (p - lo < hi - p) {
+            introsort_impl(a, lo, p, max_depth);
+            lo = p;
+        } else {
+            introsort_impl(a, p + 1, hi, max_depth);
+            hi = p + 1;
+        }
+    }
+    insertion_sort(a + lo, hi - lo);
+}
