+// LSD Radix Sort for large inputs (3 passes of 11 bits)
+static void radix_sort_lsd(uint32_t* a, size_t n) {
+    if (n == 0) return;
+    std::vector<uint32_t> buf(n);
+    constexpr size_t BUCKET_COUNT = 2048; // 11 bits
+    std::vector<uint32_t> hist(BUCKET_COUNT, 0);
+    std::vector<uint32_t> offset(BUCKET_COUNT, 0);
+    
+    // 3 passes for 32 bits (11 + 11 + 10 = 32)
+    // We use 11 bits for all passes to simplify the mask logic, last pass ignores extra buckets
+    for (int pass = 0; pass < 3; ++pass) {
+        size_t shift = pass * 11;
+        size_t buckets = (pass == 2) ? 1024 : 2048; // Last pass only needs 10 bits (1024)
+        
+        // Count frequencies
+        for (size_t i = 0; i < n; ++i) {
+            hist[(a[i] >> shift) & (buckets - 1)]++;
+        }
+        
+        // Compute offsets (exclusive scan)
+        uint32_t acc = 0;
+        for (size_t i = 0; i < buckets; ++i) {
+            offset[i] = acc;
+            acc += hist[i];
+            hist[i] = 0; 
+        }
+        
+        // Scatter
+        for (size_t i = 0; i < n; ++i) {
+            uint32_t digit = (a[i] >> shift) & (buckets - 1);
+            buf[offset[digit]++] = a[i];
+        }
+        
+        // Copy back
+        std::memcpy(a, buf.data(), n * sizeof(uint32_t));
+    }
+}
